// 1. Spatial Locality: Efficient Stride-1 Access (Row Major)
#define N 1024
int matrix[N][N];

void process_rows() {
    // Inner loop iteration loads contiguous memory (cache line efficient)
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            matrix[i][j]++; 
        }
    }
}

// 2. Poor Spatial Locality: Large Stride Access (Column Major)
#define N 1024
int matrix[N][N]; // C/C++ arrays are row-major

void process_cols() {
    // Inner loop jumps N * sizeof(int) bytes (frequent cache misses)
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < N; i++) {
            matrix[i][j]++; 
        }
    }
}

// 3. Temporal Locality: Data Reuse
int shared_data[100];
int result = 0;

void high_reuse() {
    // Data loaded in the first loop is reused in the second
    for (int i = 0; i < 100; i++) {
        shared_data[i] *= 2; 
    }
    for (int i = 0; i < 100; i++) {
        result += shared_data[i]; // Reuse (Cache hit likely)
    }
}

// 4. Cache Line Alignment (C++17)
// Prevents false sharing in concurrent systems
// assuming a 64-byte cache line size
struct alignas(64) AlignedCounter {
    volatile long long count; // Data field
    char padding[64 - sizeof(long long)]; // Pad to boundary
};

AlignedCounter thread_local_state;
